    "take": "Muse 最值得看的不是「AI 終於識幫你買嘢」，而是 Meta 正把 Agent 變成一套權限與責任系統。真正的護城河不會只是模型更聰明，而是誰能把最小權限、敏感操作確認、可追溯紀錄與可撤回做得足夠清楚，令用戶敢把真實帳戶交給它。短期應把 Muse 當成大型實驗，而不是把「有 Secure VM」理解成風險已經解決。",
    "title": "Meta 推出 Muse 個人 Agent：可連接電郵、行程與付款，權限與安全成關鍵",
    "verified": true,
    "whatHappened": "Meta 於 2026 年 9 月 8 日正式發布 Muse，定位為面向一般消費者的個人 AI Agent。Meta 官方資料顯示，Muse 會在專用的 Muse Secure VM 中運作，內有自己的瀏覽器；用戶可以選擇連接哪些 App，以及每個連接器可以讀取或執行甚麼，例如電郵只准讀取，或同時准許代為發送。Meta 表示，密碼及付款資料會存放在安全儲存區，Muse 本身看不到憑證；在發送電郵或購買等敏感操作前，系統會再次向用戶確認，並提供完整活動／審計紀錄。Meta 又稱，獨立的 Sentinel agent 與 Muse 在系統層面分隔，任何要連到互聯網的行動都需要 Sentinel 批准，必要時再要求用戶授權。產品初期在美國推出，可於 iOS、Android、muse.ai 及 WhatsApp 使用，Meta 表示大部分用途免費，另設較高用量的訂閱方案。\n\n另一方面，Reuters 報道指 Muse 原定較早推出，但 Meta 為加強安全而延後。Reuters 取得的內部測試材料顯示，測試過程曾出現斷線、可靠性不穩、非預期資料上載與私隱問題，亦有私人資料暴露的個案。Meta 對部分個別內部事件沒有逐項評論，但表示產品現已達到其安全與私隱發布標準，同時承認 Agent 仍可能出錯。這兩組資料需要一併閱讀：官方文件說明設計上的防護機制；Reuters 則顯示，即使有這些控制，實際執行層仍可能出現失誤。",
    "whatToWatch": "接下來最值得核實五件事：第一，Meta 會否公開 Muse 的完整 connector 清單，以及各 App 可授權到甚麼粒度；第二，哪些動作屬強制人手確認，付款金額、對外發送及帳戶設定是否有不同門檻；第三，正式推出後有沒有第三方研究者重現 prompt injection、私隱暴露或錯誤交易；第四，Meta 預告的 Confidential VM 是否按計劃推出，密鑰遺失、跨裝置與帳戶復原如何處理；第五，美國以外尤其香港／亞洲的推出日期、資料儲存地與合規安排。真正能改變判斷的不是更多示範影片，而是可量化的任務成功率、事故率、人工確認率與事故補救時間。",
    "whyImportant": "Muse 把 AI Agent 的競爭由 demo 推進到真正的帳戶權限、支付及第三方 App 生態。Meta 同時擁有 WhatsApp、Instagram、Facebook 等巨大分發入口，如果 Muse 的代理模式擴大，銀行、電商、旅遊、企業 SaaS 及身份服務都要重新考慮「AI 代理人」應獲得甚麼 API 權限，以及交易發生後責任如何分配。這亦會改變產品比較標準：未來 Agent 不只比推理能力，還要比工具連接、成功率、權限粒度、審計紀錄、事故率與補救能力。\n\n對市場而言，這是一個更難但更有商業價值的門檻。能把 Agent 接入真實工作流的公司，可能建立更高使用頻率與訂閱價值；同時，一次涉及付款或私隱的嚴重事故，亦可能帶來監管、信任與賠償成本。因此安全不是附加功能，而是 Agent 商業模式能否擴張的前置條件。",
