    "deepDive": "要判斷這宗事件，第一步是把「技術」與「行為」分開。Distillation 像資料壓縮或知識轉移方法，本身沒有天然的合法／非法屬性。問題在於 teacher model 是誰的、輸出怎樣取得、是否遵守 API／產品條款、是否利用大量假帳戶或代理網絡隱藏來源、是否繞過 rate limits，及 student model 最後複製的是一般知識、特定受保護內容，還是某種專有行為模式。這些細節會決定事件屬正常研究、商業競爭、違約，還是更嚴重的網絡／國安問題。\n\n第二步是理解為甚麼 frontier lab 會特別緊張。訓練最前沿模型需要大量 GPU、電力、數據、研究人才和反覆實驗。如果競爭者能以相對較低成本，透過大量查詢取得高品質推理、程式、工具使用或長鏈任務輸出，再把它當成 training signal，理論上可以節省部分探索成本。這不代表 student model 可以完整複製 teacher 的所有能力，但在某些任務上確實可能提升效率。對付費 API 公司而言，問題不只是「有人用了輸出」，而是自己的昂貴推理服務是否被反過來當成競爭模型的訓練基建。\n\n第三步是防守方式。模型供應商可以看異常查詢模式、短時間大量高價值 prompt、帳戶之間高度相似的任務、IP／付款工具關聯、輸出採樣模式及自動化行為，再配合 rate limits、身份驗證、模型行為水印、限制高風險輸出與停權。困難在於正常企業客戶、benchmark 平台、研究人員同樣可能大量查詢；如果防守過度，會傷害正常 API 使用。這是一個典型 precision / recall 問題：抓太鬆會漏掉 extraction，抓太緊會封錯客戶。\n\n第四步是「證明」比「偵測」更難。即使供應商發現一批可疑帳戶，也不等於可以單靠模型輸出證明某個後來發布的模型就是由特定 teacher 蒸餾而來。不同模型會學到相似公開知識，工程團隊亦會採用相近 benchmark 和公開論文。要把因果關係做實，通常需要帳戶／網絡證據、時間序列、查詢內容、付款與身份關聯、內部文件，甚至模型行為或訓練資料證據。這也是為甚麼目前應把美方說法寫成正式指控，而不是既定技術事實。\n\n第五步是政策後果。若美國把大規模蒸餾視為國安威脅，政策工具可能不只限於封 API 帳戶，亦可能延伸至實體清單、雲端存取、先進晶片、模型服務出口、身份驗證要求或跨境支付。這會令 AI 出口管制由「硬件能否賣」進一步變成「模型能力能否透過 API 跨境取得」。對全球開發者而言，最直接後果可能是高階模型 API 的 KYC、用量監控與地區限制增加，而不一定首先是法院訴訟。\n\n第六步是開源模型的界線。開放權重模型本身允許更多再訓練、fine-tune 或蒸餾可能性，具體仍受 licence 約束；封閉 API 則通常以服務條款限制自動抽取與用輸出訓練競爭模型。未來地緣政治升級可能令企業更重視 model provenance：不只問「模型幾好用」，還要問訓練資料／teacher signals 從何而來、授權是否清楚、會否因供應商被制裁而突然不能用。\n\n第七步是反方與限制。美方的安全擔憂有實質技術基礎，但不能由此推出「中國模型能力只是抄來」。Brookings 的國會證詞指出，中國實驗室在模型效率、MoE、quantization、長上下文等領域有真實研究創新；distillation 能提升模型，但作用有限，不能解釋全部進步。若政策分析忽略這點，容易低估中國本土工程能力，亦可能錯判出口限制的效果。\n\n最後要看這宗爭議會否由安全公告進一步變成可執行制度。如果只是一次公開點名，影響主要是外交與品牌；如果出現具體 API 禁令、制裁、KYC、雲端供應限制或法律案件，才會直接重寫跨境模型供應鏈。香港處於中美科技與國際雲端服務交界，最需要的是保留模型／雲端替代方案、清楚保存授權與使用紀錄，而不是押注某一方的政治敘事一定勝出。",
    "excerpt": "美國指控 DeepSeek、月之暗面、阿里巴巴等公司以蒸餾等方式複製美國 AI 技術；涉事方回應與可核實技術證據仍待公開。",
